-- CU-W29 B1: official MCEF catalog plus tenant-owned analytic accounts.
ALTER TABLE plan_cuenta
    ADD COLUMN IF NOT EXISTS naturaleza VARCHAR(10),
    ADD COLUMN IF NOT EXISTS es_regularizadora BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS es_oficial BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS cooperativa_id INT NULL REFERENCES cooperativa(id),
    ADD COLUMN IF NOT EXISTS estado VARCHAR(10) NOT NULL DEFAULT 'ACTIVA',
    ADD COLUMN IF NOT EXISTS acepta_movimientos BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS descripcion TEXT NULL,
    ADD COLUMN IF NOT EXISTS fecha_creacion TIMESTAMP NOT NULL DEFAULT now();

ALTER TABLE plan_cuenta ALTER COLUMN nombre TYPE TEXT;
UPDATE plan_cuenta SET naturaleza = CASE WHEN left(codigo, 1) IN ('1','4','6','8') THEN 'DEUDORA' ELSE 'ACREEDORA' END WHERE naturaleza IS NULL;
ALTER TABLE plan_cuenta ALTER COLUMN naturaleza SET NOT NULL;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_plan_cuenta_naturaleza') THEN
        ALTER TABLE plan_cuenta ADD CONSTRAINT chk_plan_cuenta_naturaleza CHECK (naturaleza IN ('DEUDORA','ACREEDORA'));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_plan_cuenta_estado') THEN
        ALTER TABLE plan_cuenta ADD CONSTRAINT chk_plan_cuenta_estado CHECK (estado IN ('ACTIVA','INACTIVA'));
    END IF;
END $$;

-- Remove bd.sql's global codigo UNIQUE after establishing the tenant-aware key.
CREATE UNIQUE INDEX IF NOT EXISTS uq_plan_cuenta_scope_codigo
    ON plan_cuenta ((COALESCE(cooperativa_id, 0)), codigo);
ALTER TABLE plan_cuenta DROP CONSTRAINT IF EXISTS plan_cuenta_codigo_key;
CREATE INDEX IF NOT EXISTS idx_plan_cuenta_padre ON plan_cuenta(plan_cuenta_padre_id);

-- Generated from investigacion/T02.txt by scripts/generate_plan_cuentas.py.

-- Keep existing detail foreign keys stable while redirecting legacy chart ids.
UPDATE detalle_asiento d
SET plan_cuenta_id = official.id
FROM plan_cuenta legacy
JOIN (VALUES
    ('100-000','100.00'), ('110-000','110.00'), ('130-000','130.00'),
    ('111-001','111.01'), ('131-001','131.05')
) AS mapping(old_code, official_code) ON mapping.old_code = legacy.codigo
JOIN plan_cuenta official ON official.codigo = mapping.official_code AND official.cooperativa_id IS NULL
WHERE d.plan_cuenta_id = legacy.id;

DELETE FROM plan_cuenta WHERE codigo IN ('111-001','131-001');
DELETE FROM plan_cuenta WHERE codigo IN ('110-000','130-000');
DELETE FROM plan_cuenta WHERE codigo = '100-000';
